# SAME-SCENARIO\n\"\"\"\naggregate_metric_stats.py\nRetrieve aggregated statistics (sum, avg, min, max, count) for a metric over a time window.\n\"\"\"\n\nfrom observability_client import ManagedMetricsClient\n\ndef aggregate_metric_stats(metric_name: str, start_time: str, end_time: str) -> dict:\n    \"\"\"Get summarised stats for the given metric and window.\n\n    Returns a dict with keys: sum, avg, min, max, count.\n    \"\"\"\n    client = ManagedMetricsClient()\n    return client.aggregate_metric_stats(metric_name, start_time, end_time)
